// Express application with all configurable values from environment variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const hpp = require('hpp');
require('dotenv').config();

const app = express();

// Configuration from environment variables with defaults
const config = {
  port: parseInt(process.env.PORT) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security headers
  csp: {
    defaultSrc: process.env.CSP_DEFAULT_SRC?.split(',') || ["'self'"],
    scriptSrc: process.env.CSP_SCRIPT_SRC?.split(',') || ["'self'", "'unsafe-inline'"],
    styleSrc: process.env.CSP_STYLE_SRC?.split(',') || ["'self'", "'unsafe-inline'"],
    imgSrc: process.env.CSP_IMG_SRC?.split(',') || ["'self'", "data:", "https:"]
  },

  // CORS
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || 
                 (config?.nodeEnv === 'production' ? [] : ['*']),

  // Rate limiting
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,

  // Body parsing
  jsonLimit: process.env.JSON_BODY_LIMIT || '10kb',
  urlencodedLimit: process.env.URLENCODED_BODY_LIMIT || '10kb',

  // Error handling
  showErrorDetails: process.env.SHOW_ERROR_DETAILS === 'true' || 
                   config?.nodeEnv === 'development'
};

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: config.csp
  }
}));

app.use(cors({
  origin: config.allowedOrigins,
  credentials: true
}));

app.use(xss());
app.use(hpp());

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMax
});
app.use(limiter);

// Body parsing with configurable limits
app.use(express.json({ limit: config.jsonLimit }));
app.use(express.urlencoded({ extended: true, limit: config.urlencodedLimit }));

// Routes
app.get('/health', (req, res) => {
  res.json({ 
