// Environment configuration validator
const requiredEnvVars = {
  production: [
    'NODE_ENV',
    'PORT',
    'SESSION_SECRET',
    'ALLOWED_ORIGINS'  // Required in production for security
  ],
  development: [
    'NODE_ENV',
    'PORT'
  ],
  test: [
    'NODE_ENV',
    'PORT'
  ]
};

const recommendedEnvVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'SESSION_SECRET',
  'LOG_LEVEL'
];

function validateEnvironment() {
  const nodeEnv = process.env.NODE_ENV || 'development';
  const missing = [];
  const warnings = [];

  // Check required environment variables
  if (requiredEnvVars[nodeEnv]) {
    requiredEnvVars[nodeEnv].forEach(varName => {
      if (!process.env[varName]) {
        missing.push(varName);
      }
    });
  }

  // Check recommended environment variables
  recommendedEnvVars.forEach(varName => {
    if (!process.env[varName]) {
      warnings.push(varName);
    }
  });

  // Check for default secrets (security risk)
  const defaultSecrets = [
    'your-super-secret-session-key-change-this',
    'your-actual-aws-access-key',
    'your-actual-aws-secret-key',
    'change-this-in-production'
  ];

  Object.entries(process.env).forEach(([key, value]) => {
    if (defaultSecrets.some(secret => value.includes(secret))) {
      warnings.push(`${key} appears to contain a default/example value`);
    }
  });

  return { missing, warnings, nodeEnv };
}

function logValidationResults(results) {
  console.log(`\n=== Environment Configuration Validation ===`);
  console.log(`Environment: ${results.nodeEnv}`);

  if (results.missing.length > 0) {
    console.log('\n❌ MISSING REQUIRED VARIABLES:');
    results.missing.forEach(varName => {
      console.log(`   - ${varName}`);
    });
    console.log('\nPlease set these variables in your .env file');
  }

  if (results.warnings.length > 0) {
    console.log('\n⚠️  RECOMMENDED VARIABLES MISSING OR USING DEFAULTS:');
    results.warnings.forEach(warning => {
      console.log(`   - ${warning}`);
    });
  }

  if (results.missing.length === 0 && results.warnings.length === 0) {
    console.log('\n✅ All environment variables are properly configured!');
  }

  console.log('===============================================\n');
}

module.exports = {
  validateEnvironment,
  logValidationResults,
  requiredEnvVars,
  recommendedEnvVars
};

