// Secure application with environment variables
require('dotenv').config();

const express = require('express');
const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Simple health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    environment: NODE_ENV,
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint - in production this should connect to a database
app.get('/users', (req, res) => {
  // Example data - in real application this should come from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);

  // Security warning in development
  if (NODE_ENV === 'development') {
    console.warn('⚠️  Running in development mode - security features may be limited');
  }
});

module.exports = app;

