// Secure Express.js application with configurable environment variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('ALLOWED_ORIGINS', 'PORT');
}

const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingVars.length > 0) {
  console.error('Missing required environment variables:', missingVars.join(', '));
  process.exit(1);
}

// Security middleware
app.use(helmet());

// CORS configuration - no fallback in production
const corsOptions = process.env.NODE_ENV === 'production' 
  ? { origin: process.env.ALLOWED_ORIGINS.split(','), credentials: true }
  : { origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000', credentials: true };
app.use(cors(corsOptions));

// Rate limiting with configurable values
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes default
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100, // 100 requests default
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware with configurable limits
const requestSizeLimit = process.env.REQUEST_SIZE_LIMIT || '10kb';
app.use(express.json({ limit: requestSizeLimit }));
app.use(express.urlencoded({ extended: true, limit: requestSizeLimit }));

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
    environment: process.env.NODE_ENV
  });
});

// Users endpoint with configurable validation
app.get('/users', (req, res) => {
  const defaultUserLimit = parseInt(process.env.DEFAULT_USER_LIMIT) || 10;
  const maxUserLimit = parseInt(process.env.MAX_USER_LIMIT) || 100;

  const { limit } = req.query;
  const userLimit = parseInt(limit) || defaultUserLimit;

  if (userLimit > maxUserLimit) {
    return res.status(400).json({ 
      error: 'Limit cannot exceed ' + maxUserLimit,
      maxAllowed: maxUserLimit
    });
  }

  // In production, this would come from a database
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { message: err.message, stack: err.stack })
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV}`);
  console.log(`CORS allowed origins: ${corsOptions.origin}`);
  console.log(`Rate limit: ${limiter.options.max} requests per ${limiter.options.windowMs/60000} minutes`);
});

module.exports = app;
EOF

